"""SHPMORPH, SUBSHAPE and FRMMORPH — how a door is drawn and moved.

The bible is plain about it (`introduction/glossary.htm`):

    "Doors in AvP are generated by morphing all the vertices in a module between
     two specified shapes. To create a door we save off two versions of the 3D
     shape, one with the door open and one with the door closed."

and `inteng/qa.htm` adds the part that matters most:

    "Any object that has been given morph data will become a prox door."

So morph data IS what makes something a door. A `DoorStrategy` without it is a
label on a module that has nothing to move, which is exactly what the first
export produced: invisible, and walk-through.

Structure, from all 761 morphs in the 63 shipped levels:

    REBSHAPE                  the wall, unchanged
    └── SHPMORPH              a container, no payload of its own
        ├── SUBSHAPE          the door leaf, a complete shape
        │   ├── SUBSHPHD      44 B header
        │   ├── SHPCENTR
        │   ├── SHPRAWVT      num_verts x 12
        │   ├── SHPVNORM      num_verts x 12
        │   ├── SHPPNORM      num_polys x 12
        │   ├── SHPPOLYS      num_polys x 36
        │   └── SHPUVCRD      4 + num_polys x 28
        └── FRMMORPH          24 + 12n bytes, n frames of three ints

`SUBSHPHD` is `SHPHEAD1` with a different prologue: it keeps the counts, the
radius and the bounds, and drops flags, lock_user, version and the name. Counts
and radii are confirmed by arithmetic on three independent sub-shapes, and the
bounds order is the one `ShapeHeaderChunk` already writes.

`FRMMORPH` is `a_flags = 0`, `a_speed = 65536` (1.0 in 16.16) and one frame of
`(-1, 1, 0)` in 714 of 714 one-frame cases. Because that frame is identical
across every door in the game, it does not carry the movement -- it names which
shape to show. The movement is the sub-shape itself.
"""
from __future__ import annotations

import struct

from ..chunk_writer import Chunk, ChunkWithChildren

# Report sizes, for the verifier and for the writer's own assertions.
SUBSHPHD_BYTES = 44
FRMMORPH_FRAME_BYTES = 12

# `FRMMORPH.a_speed` is a 16.16 multiplier and is 65536 in all 761 retail morphs,
# which is 1.0: the morph runs at real time.
FRAME_MORPH_SPEED = 65536
# The frame every one-frame retail morph uses. Three ints, not a vector.
DEFAULT_FRAME = (-1, 1, 0)


class SubShapeHeaderChunk(Chunk):
    """SUBSHPHD — the header of a door leaf."""

    identifier = "SUBSHPHD"

    def __init__(self, num_verts, num_polys, radius, max_xyz, min_xyz,
                 index=0, sub_shape_no=1):
        # +0 is zero in all 12023 retail sub-shapes. +4 is a sub-shape
        # number: -1 for a plain sub-shape, 1 for the first, and the counts
        # (761 ones, 47 twos) match the morph counts exactly, because a
        # morphed leaf is the first sub-shape of its module.
        self.index = int(index)
        self.sub_shape_no = int(sub_shape_no)
        self.num_verts = int(num_verts)
        self.num_polys = int(num_polys)
        self.radius = float(radius)
        self.max_xyz = tuple(int(v) for v in max_xyz)
        self.min_xyz = tuple(int(v) for v in min_xyz)

    def payload(self) -> bytes:
        """Serialise the 44-byte header.

        The first eight bytes are the index and the sub-shape number, not
        padding: an earlier version wrote -1 blindly and every sub-shape in the
        game disagreed at that offset.
        """
        buf = bytearray()
        buf += struct.pack("<2i", self.index, self.sub_shape_no)
        buf += struct.pack("<i", self.num_verts)
        buf += struct.pack("<i", self.num_polys)
        buf += struct.pack("<f", self.radius)
        # Bounds: max.x, min.x, max.y, min.y, max.z, min.z -- the order
        # `ShapeHeaderChunk` already uses.
        for axis in range(3):
            buf += struct.pack("<i", self.max_xyz[axis])
            buf += struct.pack("<i", self.min_xyz[axis])
        assert len(buf) == SUBSHPHD_BYTES, len(buf)
        return bytes(buf)


class FrameMorphChunk(Chunk):
    """FRMMORPH — how a sub-shape animates."""

    identifier = "FRMMORPH"

    def __init__(self, frames=None, flags=0, speed=FRAME_MORPH_SPEED):
        self.frames = [tuple(int(v) for v in f)
                       for f in (frames or [DEFAULT_FRAME])]
        self.flags = int(flags)
        self.speed = int(speed)

    def payload(self) -> bytes:
        """Serialise the flags, the speed and the frames."""
        buf = bytearray()
        buf += struct.pack("<3i", self.flags, self.speed, len(self.frames))
        for frame in self.frames:
            if len(frame) != 3:
                raise ValueError(f"a frame is three ints, got {frame!r}")
            buf += struct.pack("<3i", *frame)
        return bytes(buf)


class SubShapeChunk(ChunkWithChildren):
    """SUBSHAPE — the door leaf as a complete shape."""

    identifier = "SUBSHAPE"

    def __init__(self, children):
        super().__init__(self.identifier, children)


class ShapeMorphChunk(ChunkWithChildren):
    """SHPMORPH — a sub-shape plus the frames that move it."""

    identifier = "SHPMORPH"

    def __init__(self, sub_shape, frame_morph):
        super().__init__(self.identifier, [sub_shape, frame_morph])


def build_morph_chunk(shape_children, num_verts, num_polys, radius,
                      max_xyz, min_xyz, frames=None):
    """Return a SHPMORPH for a door leaf.

    `shape_children` are the geometry chunks of an ordinary shape, minus its
    header: the same vertex, normal, polygon and UV chunks `REBSHAPE` carries,
    because a sub-shape is a shape. Only the header differs, so the exporter
    reuses everything it already knows how to write.
    """
    header = SubShapeHeaderChunk(num_verts, num_polys, radius, max_xyz, min_xyz)
    leaf = SubShapeChunk([header] + list(shape_children))
    return ShapeMorphChunk(leaf, FrameMorphChunk(frames))
